\title{Fractal Number Theory: Hausdorff and Box-Counting Dimensions
of the Logarithmic Prime Image}
\author{Aristotle (Harmonic)}
\date{2026-06-17}

\begin{document}
\maketitle

\begin{abstract}
We study the set $S = \{\, 1/\log p : p \text{ prime} \,\} \subset \R$, the
image of the primes under the transformation $x \mapsto 1/\log x$, with the
induced metric $d(p,q) = |1/\log p - 1/\log q|$. This logarithmic lens
compresses the large primes toward the origin while leaving the small primes
spread out, and it is the natural setting in which to ask whether the primes
form a fractal. Our main theorem is that the \emph{Hausdorff dimension of $S$ is
exactly $0$}, a consequence of countability that no remetrization can
circumvent. We further prove that $S$ is bounded inside $(0, 1/\log 2]$, that
$0$ is a limit point of $S$, that the induced distance is a genuine metric, and
that the lens compresses prime gaps super-polynomially: Bertrand intervals
$(n,2n]$ of integer width $O(n)$ have logarithmic width $1/\log(n{+}1) -
1/\log(2n) \to 0$. We give an explicit metric formula and specialize it to twin
primes, which are the tightest clusters in $S$, at distance $\approx 2/(p\log^2
p)$. Finally we introduce a box-counting (Minkowski) dimension framework and a
prime-gap energy functional, and we formulate the central open problem --- the
\emph{dimensional gap} --- namely that while $\dimH(S) = 0$, the upper
box-counting dimension $\dimB(S)$ is conjecturally strictly positive. All results
stated as theorems have been formally verified.
\end{abstract}

\medskip
\noindent\textbf{Keywords:} prime numbers, Hausdorff dimension, box-counting
dimension, fractal geometry, logarithmic metric, twin primes, Minkowski
dimension.

\medskip
\noindent\textbf{MSC 2020:} 11N05, 28A78, 28A80, 11A41, 11N13.

\section{Introduction}

The primes have density zero in the integers: by the Prime Number Theorem
$\pi(x) \sim x/\log x$. Density is a one-dimensional notion of size; fractal
geometry offers a finer hierarchy. We ask whether the primes, suitably embedded,
carry fractal structure encoding arithmetic information such as the distribution
of twin primes.

Under the Euclidean metric the primes drift apart without bound. We therefore
remetrize via the \emph{logarithmic lens} $p \mapsto 1/\log p$, which
concentrates the primes into a bounded region near the origin.

\paragraph{The originating conjecture and its refutation.}
The investigation began with the heuristic that under the logarithmic metric the
primes form a fractal \emph{curve} of dimension $1 + \eps$, with $\eps > 0$
driven by twin primes, so that the truth of the twin prime conjecture would be
equivalent to $\eps > 0$. The heuristic rested on Mertens' theorem $\sum_{p\le
x} 1/p \sim \log\log x$, read as a divergent ``length'' forcing dimension
$\ge 1$. This is refuted twice over: the genuine length increment is $\sum
1/(p\log^2 p)$, which \emph{converges}; and $S$ is \emph{countable}, so
$\dimH(S) = 0$ unconditionally. The fractal content, if any, must live in a
dimension notion insensitive to countability --- the box-counting dimension.

\section{Preliminaries}

We work in $\R$ with its standard topology and Hausdorff dimension $\dimH$. We
recall:
\begin{itemize}[nosep]
\item \textbf{(GMT-1)} Every countable subset of a metric space has Hausdorff
dimension $0$: cover the $k$-th point by a ball of radius $\delta\,2^{-k}$; the
$s$-Hausdorff premeasure is $\le \delta^s\sum 2^{-ks} \to 0$ for all $s>0$.
\item \textbf{(GMT-2)} $\dimH$ is monotone and stable under countable unions.
\end{itemize}
We also use that $\log$ is strictly increasing and positive on $(1,\infty)$, that
$\log p > 0$ for primes $p \ge 2$, and that $1/\log n \to 0$.

\section{Core Definitions}

\begin{definition}[Logarithmic prime image]
$S := \{\, x \in \R : \exists\, p \in \N,\ p \text{ prime},\ x = 1/\log p \,\}.$
\end{definition}

\begin{definition}[Logarithmic prime metric]
For $p,q \in \N$, $\ d(p,q) := \left| 1/\log p - 1/\log q \right|.$
\end{definition}

\begin{definition}[Box-counting number]
For $S \subseteq \R$ and $\eps > 0$,
\[
N(S,\eps) := \#\{\text{grid cells of width }\eps\text{ meeting }S\}
= \#\bigl(\,[\,\lfloor \inf S/\eps\rfloor,\ \lceil \sup S/\eps\rceil\,]\cap\mathbb{Z}\,\bigr),
\]
and $N(S,\eps) := 0$ for $\eps \le 0$.
\end{definition}

\begin{definition}[Upper box-counting dimension]
$\dimB(S) := \limsup_{\eps\to 0^+} \dfrac{\log N(S,\eps)}{\log(1/\eps)}.$
\end{definition}

\begin{definition}[Prime-gap energy]
For $N \in \N$ and $s \in \R$,
\[
E(N,s) := \sum_{\substack{k < N \\ k,\,k+2 \text{ prime}}}
\left| 1/\log k - 1/\log(k+2)\right|^{s}.
\]
\end{definition}

\section{Countability and Hausdorff Dimension}

\begin{theorem}[Countability]
$S$ is countable.
\end{theorem}
\begin{proof}[Proof sketch]
$S$ is the image of the countable set of primes under $p \mapsto 1/\log p$,
hence a subset of a countable range.
\end{proof}

\begin{theorem}[Main Theorem]\label{thm:main}
$\dimH(S) = 0.$
\end{theorem}
\begin{proof}[Proof sketch]
Immediate from countability and \textbf{(GMT-1)}. The result is robust under
remetrization: replacing the Euclidean metric by $d$ preserves countability, so
no metric on the prime set yields positive Hausdorff dimension.
\end{proof}

\begin{remark}
Theorem~\ref{thm:main} refutes the ``dimension $1+\eps$'' conjecture. The twin
prime conjecture is logically independent of $\dimH(S)$, which is
unconditionally $0$.
\end{remark}

\section{Metric Axioms}

\begin{theorem}[Symmetry]
$d(p,q) = d(q,p)$.
\end{theorem}
\begin{theorem}[Triangle inequality]
$d(p,r) \le d(p,q) + d(q,r)$.
\end{theorem}
\begin{theorem}[Identity of indiscernibles]
For primes $p,q$: $d(p,q) = 0 \iff p = q$.
\end{theorem}
\begin{proof}[Proof sketch]
$d(p,q)=0 \iff \log p = \log q$; injectivity of $\log$ on $(1,\infty)$ and of the
cast $\N\to\R$ give $p=q$. The converse is trivial.
\end{proof}

Thus $(\text{primes}, d)$ is a metric space, isometric to $(S, |\cdot|)$.

\section{Boundedness}

\begin{theorem}[Positivity]
For every prime $p$, $1/\log p > 0$.
\end{theorem}
\begin{theorem}[Upper bound]
For every prime $p$, $1/\log p \le 1/\log 2$.
\end{theorem}
\begin{theorem}[Confinement]
$S \subseteq (0, 1/\log 2]$.
\end{theorem}
The largest element of $S$ is $1/\log 2 \approx 1.442695$, attained at $p=2$.

\section{Accumulation at the Origin}

\begin{lemma}
$1/\log n \to 0$ as $n \to \infty$.
\end{lemma}
\begin{proposition}
For every $\eps > 0$ there is a prime $p$ with $1/\log p < \eps$.
\end{proposition}
\begin{proof}[Proof sketch]
Take a prime $p > \lfloor e^{1/\eps}\rfloor$ (Euclid); then $\log p > 1/\eps$.
\end{proof}
\begin{theorem}[Zero is a limit point]
$0 \in \closure(S)$.
\end{theorem}
Since $0 \notin S$, the point $0$ is a genuine accumulation point; $S$ is
scattered with unique limit point $0$.

\section{Gap Compression via Bertrand's Postulate}

\begin{lemma}[Bertrand sandwich]
For $n\ge 1$ there is a prime $p$ with $n < p \le 2n$.
\end{lemma}
\begin{lemma}
If $p$ is prime, $p \le 2n$, $n\ge 2$, then $1/\log(2n) \le 1/\log p$.
\end{lemma}
\begin{lemma}
If $p$ is prime, $n < p$, $n\ge 1$, then $1/\log p \le 1/\log(n{+}1)$.
\end{lemma}
\begin{theorem}[Spacing vanishes]
$1/\log(n{+}1) - 1/\log(2n) \to 0$ as $n \to \infty$.
\end{theorem}
An integer interval $(n,2n]$ of width $n$ collapses to a sliver of logarithmic
width $\approx \log 2/\log^2 n = O(1/\log^2 n)$.

\section{Explicit Metric Formula and Diameter}

\begin{theorem}[Metric formula]
For primes $p,q$, $\ d(p,q) = \dfrac{|\log q - \log p|}{\log p \cdot \log q}.$
\end{theorem}
\begin{theorem}[Diameter bound]
$\diam(S) \le 1/\log 2$.
\end{theorem}
\begin{theorem}[Maximum attained]
$1/\log 2 \in S$, witnessed by $p=2$; the diameter bound is exact.
\end{theorem}

\section{Twin Primes as Tightest Clusters}

\begin{theorem}[Twin-prime distance]
For a twin pair $(p, p+2)$ with $p, p+2$ prime and $p \ge 3$,
\[
d(p, p+2) = \frac{\log(p+2) - \log p}{\log p \cdot \log(p+2)}.
\]
\end{theorem}
Since $\log(p+2)-\log p = \log(1 + 2/p) \approx 2/p$, we get $d(p,p+2) \approx
2/(p\log^2 p)$: twin pairs are microscopic dimers riding the accumulation toward
$0$, contributing fine structure visible to box counting but not to Hausdorff
dimension.

\section{The Dimensional Gap}

Hausdorff dimension uses covers of arbitrary radii and shrinks countable sets to
$0$; box-counting dimension uses a uniform grid and is \emph{blind to
countability}.

\begin{theorem}[Dimensional gap, proved half]
$\dimH(S) = 0$ and $0 \in \closure(S)$.
\end{theorem}

\begin{conjecture}[Strict dimensional gap]
$\dimB(S) > 0$; in particular $\dimH(S) = 0 < \dimB(S)$.
\end{conjecture}

\begin{conjecture}[Value]
$\dimB(S) = 1/2$.
\end{conjecture}

\noindent\textbf{Heuristic.} With $a_k = 1/\log p_k$ decreasing to $0$ and
$a_k - a_{k+1} \asymp 1/(p_k \log^2 p_k)$, resolving the accumulation at scale
$\eps$ gives $N(S,\eps) \asymp \eps^{-1/2}$. Finite computation ($p \le 10^7$)
yields $\log N/\log(1/\eps) \approx 0.7$ drifting slowly; settling the exact
value is the central open problem.

\section{Discussion and Future Work}

The scale-invariant geometry of the logarithmic prime image is trivial
($\dimH = 0$, forced by countability); the resolution-dependent geometry carries
the fractal content via box counting. The methodological lesson: a divergent
arithmetic sum need not be a geometric length, and box-counting (Minkowski)
dimension --- not length --- is the right invariant separating dust from curve.

\noindent\textbf{Open problems.}
\begin{enumerate}[nosep]
\item Compute $\dimB(S)$; the leading conjecture is $1/2$.
\item Show $\closure(S) = S \cup \{0\}$ (scattered, Cantor--Bendixson rank $1$).
\item Prove the arc length telescopes to $a_1 = 1/\log 2$ (finite length).
\item Show the twin sub-dust has finite length $\le 1/\log 2$; analyze the
critical exponent of $E(N,s)$.
\item Classify which slowly-varying lenses $\varphi$ yield positive box
dimension.
\end{enumerate}

\section{Conclusion}

Under the logarithmic lens the primes form a bounded, countable, scattered set
$S \subset (0, 1/\log 2]$ accumulating at $0$, with large primes compressed
super-polynomially and twin primes forming the tightest clusters. Its Hausdorff
dimension is unconditionally $0$. The genuine fractal question --- the size of the
dimensional gap $\dimB(S) > 0$ --- remains open and is the natural successor to the
refuted ``dimension $1 + \eps$'' conjecture.

\end{document}

