"""Box-counting estimator for dim_B of the logarithmic prime image."""
from __future__ import annotations
import math

def primes_up_to(limit: int) -> list[int]:
    sieve = [True] * (limit + 1)
    sieve[0] = sieve[1] = False
    for i in range(2, int(limit ** 0.5) + 1):
        if sieve[i]:
            for j in range(i * i, limit + 1, i):
                sieve[j] = False
    return [i for i, v in enumerate(sieve) if v]

def box_dimension_table(limit: int = 2_000_000, scales: int = 12) -> list[tuple[float, int, float]]:
    pts = [1.0 / math.log(p) for p in primes_up_to(limit)]
    rows: list[tuple[float, int, float]] = []
    eps = 0.1
    for _ in range(scales):
        n = len({math.floor(x / eps) for x in pts})
        rows.append((eps, n, math.log(n) / math.log(1.0 / eps)))
        eps /= 2.0
    return rows

if __name__ == "__main__":
    for eps, n, r in box_dimension_table():
        print(f"eps={eps:.2e}  N={n:6d}  log N/log(1/eps)={r:.4f}")

"""Twin-prime distances under the logarithmic lens and their asymptotics."""
from __future__ import annotations
import math

def is_prime(n: int) -> bool:
    if n < 2: return False
    if n % 2 == 0: return n == 2
    d = 3
    while d * d <= n:
        if n % d == 0: return False
        d += 2
    return True

def twin_distance(p: int) -> tuple[float, float]:
    """Return (exact d(p,p+2), asymptotic 2/(p log^2 p)) for a twin pair."""
    exact = abs(1 / math.log(p) - 1 / math.log(p + 2))
    asymp = 2.0 / (p * math.log(p) ** 2)
    return exact, asymp

if __name__ == "__main__":
    for p in range(3, 100000):
        if is_prime(p) and is_prime(p + 2):
            e, a = twin_distance(p)
            if p in (3, 11, 29, 101, 1019, 10007):
                print(f"p={p:6d}  d={e:.3e}  ~2/(p log^2 p)={a:.3e}")

